/*
 * A146898  Lower polynomial approximation of Eulerian numbers:
 *          t0(n,m)=If[Mod[2*Binomial[n, m], 2] - Mod[Binomial[n, m], 2] == 0,
 *          Binomial[n, m]/2, Binomial[n, m] + 1]; p(x,n)=If[n == 0, 1, (x +
 *          1)^n + Sum[t0(n,m)*x^m*(1 + x^(n - 2*m)), {m, 1, n - 1}]].
 * https://oeis.org/A146898
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = coefficient t(r,c) of the triangle generated by p(x,r),
 *            where r = floor((sqrt(8*n+1)-1)/2) and c = n - r*(r+1)/2. For
 *            the coefficient: t(r,0) = t(r,r) = 1; For 1 ≤ c ≤ r-1, let b =
 *            binom(r,c). If b is even, t = 2*b; otherwise t = 3*b + 2
 * Range:     u8 n <= 58, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <math.h>

seq_t a(idx_t n)
{
    /* Find row r containing the n‑th flattened element */
    idx_t r = (idx_t)((sqrtl((long double)8*n + 1.0L) - 1.0L) / 2.0L);

    /* First index of row r */
    idx_t first = (idx_t)(((__uint128_t)r * (r + 1)) / 2);
    idx_t c = n - first;           /* column within the row */

    if (c == 0 || c == r)
        return (seq_t)1;

    /* Reduce k to ≤ r/2 for efficiency */
    idx_t k = c;
    if (k > r - k)
        k = r - k;

    /* Compute binomial coefficient bin = binom(r, k) */
    seq_t bin = 1;
    for (idx_t i = 1; i <= k; ++i)
        bin = bin * (r - i + 1) / i;

    /* Determine parity of the binomial coefficient */
    if ((bin & 1) == 0)          /* even */
        return bin * 2;
    else                         /* odd */
        return bin * 3 + 2;
}
